### Possible Implementation

Optimizat CODE：

common_presets common_preset_context::load_from_models_dir(const std::string & models_dir) const {
    if (!std::filesystem::exists(models_dir) || !std::filesystem::is_directory(models_dir)) {
        throw std::runtime_error(string_format("error: '%s' does not exist or is not a directory\n", models_dir.c_str()));
    }

    std::vector<local_model> models;
    auto scan_subdir = [&models](const std::string & subdir_path, const std::string & name) {
        auto files = fs_list(subdir_path, false);
        common_file_info model_file;
        common_file_info first_shard_file;
        common_file_info mmproj_file;
        for (const auto & file : files) {
            if (string_ends_with(file.name, ".gguf")) {
                if (file.name.find("mmproj") != std::string::npos) {
                    mmproj_file = file;
                } else if (file.name.find("-00001-of-") != std::string::npos) {
                    first_shard_file = file;
                } else {
                    model_file = file;
                }
            }
        }
        // single file model
        local_model model{
            /* name        */ name,
            /* path        */ first_shard_file.path.empty() ? model_file.path : first_shard_file.path,
            /* path_mmproj */ mmproj_file.path // can be empty
        };
        if (!model.path.empty()) {
            models.push_back(model);
        }
    };

    auto files = fs_list(models_dir, true);
    bool has_subdir = false;
    for (const auto & file : files) {
        if (file.is_dir) {
            has_subdir |= true;
            scan_subdir(file.path, file.name);
            auto infiles = fs_list(file.path, true);
            for (const auto & infile : infiles) {
                if (infile.is_dir) {
                    scan_subdir(infile.path, infile.name);
                }
            }
        } else {
            has_subdir |= false;
        }
    }
    if(!has_subdir) {
        // if there is no subdir, treat the main dir as the model dir
        auto models_path = std::filesystem::path(models_dir);
        auto dir_name = models_path.filename().string();
        if(dir_name.empty() && models_path.has_parent_path()) {
            dir_name = models_path.parent_path().filename().string();
        }
        scan_subdir(models_dir, dir_name);
    }

    // convert local models to presets
    common_presets out;
    for (const auto & model : models) {
        common_preset preset;
        preset.name = model.name;
        preset.set_option(*this, "LLAMA_ARG_MODEL", model.path);
        if (!model.path_mmproj.empty()) {
            preset.set_option(*this, "LLAMA_ARG_MMPROJ", model.path_mmproj);
        }
        out[preset.name] = preset;
    }

    return out;
}

 The above code has been tested by me and works well. Moreover, it resolves the issue where the vision component fails to load when directly loading the primary directory where the model is located.

### Summary

When a single token names the same expert in more than one of its `ids` slots,
the CUDA backend disagrees with the CPU reference, and in some shapes dies
with an illegal memory access. `ggml.h` documents no uniqueness requirement on
`ids`, and the CPU backend handles repeats fine, so the two backends currently
implement different semantics.

`tests/test-backend-ops.cpp` never exercises this: `init_mul_mat_id_tensors`
fills each ids row with `i % n_mats` and shuffles it, so within a row the ids
are distinct by construction.

### Reproducer

The patch below adds a `repeat_ids` mode to `test_mul_mat_id` and registers
cases across f16/q8_0/q4_0, batch 1/16/256, broadcast and non-broadcast `b`.
Mode 1 repeats every pair (`data[i] = (i/2) % n_mats`); mode 2 repeats exactly
one pair per row, so that the size of the error shows how much of the output
is affected.

```sh
git apply repeated-ids-repro.patch
cmake --build build --target test-backend-ops -j
./build/bin/test-backend-ops -o MUL_MAT_ID
```

