## What happens

On Intel multi-GPU SYCL, each `sycl::malloc_device` call gets a 1:1 host-side mirror mapped through the kernel driver's GTT. The mirror is accounted as kernel DRM memory, so it does not appear in `free`, `ps`, `VmRSS`, or any of the standard Linux RAM counters. It is only visible in `/proc/$PID/fdinfo/$fd` as `drm-total-gtt`.

A model that fits in combined VRAM consumes an equal amount of system RAM as GTT shadow. A 35 GB model across two GPUs runs fine until other workloads push the host past 64 GB and the process is OOM-killed.

## Reproducer

Standalone, no llama.cpp needed. Allocates 4 GiB with `sycl::malloc_device` on each detected Intel GPU and prints VmRSS and fdinfo GTT before, after allocation, after free.

```cpp
// Minimal reproducer: sycl::malloc_device on dual Intel discrete GPU
// creates host-side GTT mirror of device allocations, invisible to VmRSS.
// Detectable only via /proc/self/fdinfo/*/drm-total-gtt.
//
// Usage:
//   icpx -fsycl repro.cpp -o repro
//   ./repro                                          # both GPUs
//   ONEAPI_DEVICE_SELECTOR=level_zero:0 ./repro      # single GPU

#include <sycl/sycl.hpp>
#include <cstdio>
#include <cstdlib>
#include <string>
#include <vector>
#include <fstream>
#include <filesystem>
#include <sstream>

static void report_gtt(const char * tag) {
    long rss_kb = 0;
    std::ifstream st("/proc/self/status");
    std::string line;
    while (std::getline(st, line)) {
        if (line.rfind("VmRSS:", 0) == 0) {
            sscanf(line.c_str(), "VmRSS: %ld kB", &rss_kb);
            break;
        }
    }

    printf("=== %s ===\n", tag);
    printf("  VmRSS: %ld KiB\n", rss_kb);

    for (auto & entry : std::filesystem::directory_iterator("/proc/self/fdinfo")) {
        std::ifstream f(entry.path());
        std::string pdev;
        long gtt = -1, vram = -1;
        std::string ln;
        while (std::getline(f, ln)) {
            if (ln.rfind("drm-pdev:", 0) == 0)              pdev = ln.substr(ln.find_last_of(' ') + 1);
            else if (ln.rfind("drm-total-gtt:", 0) == 0)    sscanf(ln.c_str(), "drm-total-gtt: %ld", &gtt);
            else if (ln.rfind("drm-total-vram0:", 0) == 0)  sscanf(ln.c_str(), "drm-total-vram0: %ld", &vram);
        }
        if (gtt > 100) {
            printf("  fd=%s pdev=%s vram=%ld KiB  gtt=%ld KiB\n",
                   entry.path().filename().c_str(), pdev.c_str(), vram, gtt);
        }
    }
    fflush(stdout);
}

int main() {
    auto devs = sycl::device::get_devices(sycl::info::device_type::gpu);
    std::vector<sycl::device> gpus;
    for (auto & d : devs) {
        std::string name = d.get_info<sycl::info::device::name>();
        if (name.find("Intel") != std::string::npos || name.find("Arc") != std::string::npos) {
            gpus.push_back(d);
            printf("GPU: %s\n", name.c_str());
        }
    }
    if (gpus.empty()) { fprintf(stderr, "no Intel GPU found\n"); return 1; }

    report_gtt("before");

    const size_t per_gpu = 4ULL * 1024 * 1024 * 1024;
    std::vector<sycl::queue> qs;
    std::vector<void*> ptrs;
    for (auto & d : gpus) {
        sycl::queue q(d);
        void * p = sycl::malloc_device(per_gpu, q);
        if (!p) { fprintf(stderr, "malloc_device failed\n"); return 2; }
        q.memset(p, 0, per_gpu).wait();
        qs.push_back(q);
        ptrs.push_back(p);
    }

    report_gtt("after 4 GiB malloc_device per GPU");

    for (size_t i = 0; i < ptrs.size(); ++i) sycl::free(ptrs[i], qs[i]);
    report_gtt("after free");
    return 0;
}
```

